parameters.jsCode:
const raw = $input.first().json.text;

let parsed;
try {
  parsed = JSON.parse(raw);

  // Only return parsed if it's an object or array
  if (typeof parsed === 'object') {
    return [{ json: { output: parsed } }];
  } else {
    throw new Error('Parsed value is not an object');
  }
} catch (e) {
  // Return the raw text if not JSON
  return [{ json: { output: raw } }];
}
